card.background-image:
[[[
  if (!entity || !entity.attributes) return 'none';
  var p = entity.entity_id.split('.')[1].replace(/_plant$/, '');
  var moisture = states['sensor.' + p + '_moisture'];
  if (!moisture || !moisture.attributes) return 'none';
  var dn = moisture.attributes.friendly_name.split(' ').slice(0,-1).join('_').toLowerCase()
    .split('ü').join('u').split('ö').join('o').split('ä').join('a').split('ß').join('ss');
  var img = states['image.' + dn + '_benutzerbild'];
  return img ? 'url(' + img.attributes.entity_picture + ')' : 'none';
]]]

